import random, json
r = random.Random(51)
def val(d):
    x = r.random()
    if d < 3 and x < 0.4:
        return lay(d + 1)
    if x < 0.6:
        return [r.randint(0, 9) for _ in range(r.randint(0, 3))]
    return r.choice([1, 2.0, True, None, 'v'])
def lay(d):
    o = {}
    for _ in range(r.randint(1, 5)):
        n = r.choice(['a', 'b', 'c-d', 'e'])
        k = r.random()
        if k < 0.2:
            o['-' + n] = None
        elif k < 0.35:
            o[n + '+'] = [r.randint(0, 9)]
        else:
            o[n] = val(d)
    return o
